"""Bundled emoji shortcode dataset (assets/emoji.json, generated by
scripts/gen_emoji_data.py from the `emoji` package — no runtime dependency).

Each entry is (shortcode, char, category); category ordering for the picker's
Emojis tab is defined here, with Component last (Chatterino parity).
"""

from __future__ import annotations

import json
import logging
import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

log = logging.getLogger(__name__)

DATASET_PATH = Path(__file__).resolve().parent.parent / "assets" / "emoji.json"

# Picker tab order for the Emojis list; Component is appended last.
CATEGORY_ORDER = (
    "Smileys & Emotion",
    "People & Body",
    "Animals & Nature",
    "Food & Drink",
    "Travel & Places",
    "Activities",
    "Objects",
    "Symbols",
    "Flags",
    "Component",
)


@dataclass(frozen=True)
class EmojiEntry:
    shortcode: str
    char: str
    category: str


@lru_cache(maxsize=1)
def emoji_dataset() -> tuple[EmojiEntry, ...]:
    """All bundled emoji; empty tuple when the asset is missing/corrupt."""
    try:
        data = json.loads(DATASET_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, UnicodeDecodeError) as exc:
        log.warning("Could not load %s: %s — emoji completion disabled", DATASET_PATH, exc)
        return ()
    return tuple(
        EmojiEntry(shortcode=name, char=char, category=str(category))
        for name, char, category in data
        if name and char
    )


# `:name:` with no spaces or colons inside; only known names are replaced, so
# times like 10:30:45 and unknown `:words:` stay as typed.
_SHORTCODE_RE = re.compile(r":([^:\s]+):")


@lru_cache(maxsize=1)
def _chars_by_shortcode() -> dict[str, str]:
    return {entry.shortcode: entry.char for entry in emoji_dataset()}


def expand_shortcodes(text: str) -> str:
    """`:grinning_face:` -> 😀 for every known shortcode in `text`. The emote
    picker and autocomplete insert shortcodes; both chats need the real
    character (Twitch and YouTube would otherwise show the literal text)."""
    if ":" not in text:
        return text
    chars = _chars_by_shortcode()
    return _SHORTCODE_RE.sub(lambda m: chars.get(m[1], m[0]), text)
